1. Erstellen eines Fensters mit der Bibliothek SDL (Simple DirectMedia Layer).
2. Laden von Spielfeldbildern und Speichern in einer Texturen-Struktur von SDL.
3. Implementierung eines Spielfeldes mit einer Matrix, um die Positionen der Schlange und der Früchte zu speichern.
4. Implementierung von Ereignissen, wie z.B. Tastatureingaben, um die Bewegung der Schlange zu steuern.
5. Implementierung einer Logik, um die Schlange zu bewegen und die Früchte zu verzehren, wobei die Schlange wächst.
6. Implementierung einer Logik, um das Spiel zu beenden, wenn die Schlange sich selbst verschluckt oder das Spielfeld vollständig durchquert.

Hier ein Beispielcode in C, der diese Grundlagen beinhaltet:

```c
#include <stdio.h>
#include <stdlib.h>
#include <SDL2/SDL.h>

#define WINDOW_WIDTH 800
#define WINDOW_HEIGHT 600

// Struktur für die Spielfeld-Texturen
typedef struct {
    SDL_Texture* texture;
    int width;
    int height;
} Texture;

// Struktur für das Spielfeld
typedef struct {
    int width;
    int height;
    int fruit_x;
    int fruit_y;
    int snake_x[100]; // Platz für maximal 100 Schlängelteile
    int snake_y[100];
    int snake_length;
} Field;

// Funktion zum initialisieren des Fensters und der SDL-Bibliothek
int initSDL() {
    SDL_Init(SDL_INIT_VIDEO);
    SDL_Window* window = SDL_CreateWindow("Snake Game",
            SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
            WINDOW_WIDTH, WINDOW_HEIGHT, SDL_WINDOW_SHOWN);
    if (!window) {
        printf("Fehler beim Erstellen des Fensters: %s\n", SDL_GetError());
        return 0;
    }
    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);
    if (!renderer) {
        printf("Fehler beim Erstellen des Renderers: %s\n", SDL_GetError());
        SDL_DestroyWindow(window);
        return 0;
    }
    return renderer;
}

// Funktion zum laden der Spielfeld-Texturen
Texture* loadTexture(SDL_Renderer* renderer, const char* filePath) {
    SDL_Surface* surface = SDL_LoadBMP(filePath);
    if (!surface) {
        printf("Fehler beim Laden der Texture: %s\n", SDL_GetError());
        return NULL;
    }
    SDL_Texture* texture = SDL_CreateTextureFromSurface(renderer, surface);
    if (!texture) {
        printf("Fehler beim Erstellen der Texture: %s\n", SDL_GetError());
        SDL_FreeSurface(surface);
        return NULL;
    }
    int width = surface->w;
    int height = surface->h;
    SDL_FreeSurface(surface);
    Texture* result = (Texture*)malloc(sizeof(Texture));
    result->texture = texture;
    result->width = width;
    result->height = height;
    return result;
}

// Funktion zum zeichnen einer Texture auf das Fenster
void drawTexture(SDL_Renderer* renderer, Texture* texture, int x, int y) {
    SDL_Rect dstRect = { x, y, texture->width, texture->height };
    SDL_RenderCopy(renderer, texture->texture, NULL, &dstRect);
}

// Funktion zum initialisieren des Spielfeldes
Field* initField(int width, int height) {
    Field* result = (Field*)malloc(sizeof(Field));
    result->width = width;
    result->height = height;
    result->fruit_x = rand() % width;
    result->fruit_y = rand() % height;
    result->snake_length = 1;
    return result;
}

// Funktion zum bewegen der Schlange
void moveSnake(Field* field, int direction) {
    int head_x = field->snake_x[field->snake_length - 1];
    int head_y = field->snake_y[field->snake_length - 1];
    int tail_x = field->snake_x[field->snake_length - 2];
    int tail_y = field->snake_y[field->snake_length - 2];
    switch (direction) {
        case SDL_SCANCODE_UP:
            head_x -= 1;
            break;
        case SDL_SCANCODE_DOWN:
            head_x += 1;
            break;
        case SDL_SCANCODE_LEFT:
            head_y -= 1;
            break;
        case SDL_SCANCODE_RIGHT:
            head_y += 1;
            break;
    }
    // Schlange bewegen
    for (int I = field->snake_length - 2; I >= 0; i--) {
        field->snake_x[i + 1] = field->snake_x[i];
        field->snake_y[i + 1] = field->snake_y[i];
    }
    field->snake_x[0] = head_x;
    field->snake_y[0] = head_y;
    // Frucht essen
    if (head_x == field->fruit_x && head_y == field->fruit_y) {
        field->snake_length++;
        field->fruit_x = rand() % field->width;
        field->fruit_y = rand() % field->height;
    }
    // Selbstverschluckung prüfen
    for (int I = 1; I < field->snake_length; i++) {
        if (head_x == field->snake_x[i] && head_y == field->snake_y[i]) {
            printf("Game over! ");
            return;
        }
    }
    // Spielfeld vollständig durchquert prüfen
    if (head_x < 0 || head_x >= field->width || head_y < 0 || head_y >= field->height) {
        printf("Game over! ");
        return;
    }
}

// Hauptfunktion des Spiels
int main() {
    SDL_Renderer* renderer = initSDL();
    if (!renderer) {
        return 1;
    }
    Texture* fieldTexture = loadTexture(renderer, "field.bmp");
    Texture* fruitTexture = loadTexture(renderer, "fruit.bmp");
    Field* field = initField(30, 20);

    // Ereignisse abonnieren
    SDL_Event event;
    SDL_PollEvent(&event);
    while (event.type != SDL_QUIT) {
        if (event.type == SDL_KEYDOWN) {
            moveSnake(field, event.key.keysym.sym);
        }
        SDL_RenderClear(renderer);
        drawTexture(renderer, fieldTexture, 0, 0);
        drawTexture(renderer, fruitTexture, field->fruit_x * 25, field->fruit_y * 25);
        for (int I = 0; I < field->snake_length; i++) {
            drawTexture(renderer, fruitTexture, field->snake_x[i] * 25, field->snake_y[i] * 25);
        }
        SDL_RenderPresent(renderer);
        SDL_Delay(100);
        SDL_PollEvent(&event);
    }
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(SDL_GetWindowFromID(renderer));
    SDL_Quit();
    free(field);
    free(fruitTexture);
    free(fieldTexture);
    return 0;
}
```

